import{_ as t,o as a,c as i,a5 as n}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"UC 03 — Media Package & Campaign (UC-32 → UC-41)","description":"","frontmatter":{},"headers":[],"relativePath":"ba/use-cases/03-media-package-campaign.md","filePath":"ba/use-cases/03-media-package-campaign.md"}'),o={name:"ba/use-cases/03-media-package-campaign.md"};function s(r,e,l,c,d,g){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="uc-03-—-media-package-campaign-uc-32-→-uc-41" tabindex="-1">UC 03 — Media Package &amp; Campaign (UC-32 → UC-41) <a class="header-anchor" href="#uc-03-—-media-package-campaign-uc-32-→-uc-41" aria-label="Permalink to &quot;UC 03 — Media Package &amp; Campaign (UC-32 → UC-41)&quot;">​</a></h1><p>&gt; <a href="./../00-overview.html">&lt;&lt; Về Overview</a> · Nguồn FR: <a href="./../04-media-package-campaign.html">04-media-package-campaign.md</a> &gt; Nguồn UC gốc: <code>Các FR của hệ thống - Use Case.csv</code> &gt; <strong>Thứ tự chuẩn:</strong> Workspace → Package (chọn/đàm phán/approve) → Campaign (tạo/approve → auto-gen backlog) → Content Request (kênh bổ sung, độc lập).</p><h2 id="bang-tong-hop" tabindex="-1">Bảng tổng hợp <a class="header-anchor" href="#bang-tong-hop" aria-label="Permalink to &quot;Bảng tổng hợp&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UC ID</th><th>Use Case</th><th>Actor(s)</th><th>Related FR</th></tr></thead><tbody><tr><td>UC-32</td><td>Create Media Package Template</td><td>OWNER/MANAGER</td><td>3.5.1</td></tr><tr><td>UC-33</td><td>View Media Package Template</td><td>CLIENT</td><td>3.5.2</td></tr><tr><td>UC-34</td><td>Negotiate &amp; Request Media Package</td><td>CLIENT/OWNER/MANAGER</td><td>3.5.3</td></tr><tr><td>UC-35</td><td>Approve Media Package</td><td>OWNER/MANAGER/CLIENT</td><td>3.5.4</td></tr><tr><td>UC-36</td><td>Create Media Campaign</td><td>OWNER/MANAGER/CLIENT</td><td>3.5.5</td></tr><tr><td>UC-37</td><td>Approve &amp; Launch Media Campaign</td><td>OWNER/MANAGER/CLIENT</td><td>3.5.6</td></tr><tr><td>UC-38</td><td>Create Content Request</td><td>CLIENT</td><td>3.5.7</td></tr><tr><td>UC-39</td><td>Process Content Request Status</td><td>MANAGER</td><td>3.5.8</td></tr><tr><td>UC-40</td><td>Update Content Request</td><td>CLIENT</td><td>3.5.9</td></tr><tr><td>UC-41</td><td>Cancel Content Request</td><td>CLIENT</td><td>3.5.10</td></tr></tbody></table><hr><h2 id="uc-32-—-create-media-package-template" tabindex="-1">UC-32 — Create Media Package Template <a class="header-anchor" href="#uc-32-—-create-media-package-template" aria-label="Permalink to &quot;UC-32 — Create Media Package Template&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> OWNER/MANAGER</li><li><strong>Description:</strong> Choose from pre-built media package templates created by Admin, or customize a new package for the Agency.</li><li><strong>Precondition:</strong> Workspace already created (Package selection happens right after Workspace creation, before inviting Client).</li><li><strong>Main Flow:</strong><ol><li>OWNER/MANAGER opens Media Package selection screen.</li><li>Selects an Admin-provided template, or creates a custom package (name, duration, scope).</li><li>System stores selection as a reference ID (<code>workspace_media_packages</code> → template or custom package).</li></ol></li><li><strong>Alternate Flow:</strong><ul><li>A1. Package not set at Workspace creation time → system notifies Manager to complete this step.</li></ul></li></ul><h2 id="uc-33-—-view-media-package-template" tabindex="-1">UC-33 — View Media Package Template <a class="header-anchor" href="#uc-33-—-view-media-package-template" aria-label="Permalink to &quot;UC-33 — View Media Package Template&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> CLIENT</li><li><strong>Description:</strong> Client views the sample media strategy templates (scope, staffing, duration) provided by the Agency.</li><li><strong>Precondition:</strong> Client has been invited into the Workspace.</li><li><strong>Main Flow:</strong><ol><li>CLIENT opens the proposed Media Package.</li><li>System displays package details: by duration (&quot;in X weeks, deliver Y&quot;), by budget (&quot;for amount Z, deliver Y&quot;), or full-delegation (Agency decides method, must hit agreed KPI).</li></ol></li></ul><h2 id="uc-34-—-negotiate-request-media-package" tabindex="-1">UC-34 — Negotiate &amp; Request Media Package <a class="header-anchor" href="#uc-34-—-negotiate-request-media-package" aria-label="Permalink to &quot;UC-34 — Negotiate &amp; Request Media Package&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> CLIENT/OWNER/MANAGER</li><li><strong>Description:</strong> Client submits change requests (price, timeline, format) on a sample package; Owner/Manager respond until both sides finalize the package.</li><li><strong>Precondition:</strong> A proposed Media Package exists in the Workspace.</li><li><strong>Main Flow:</strong><ol><li>CLIENT reviews the package, submits a change request (price/timeline/format/event).</li><li>OWNER/MANAGER responds: accept, reject, or counter-propose.</li><li>Loop steps 1–2 until both sides converge on a final package.</li></ol></li><li><strong>Note:</strong> CLIENT is the actual actor performing negotiation actions; OWNER/MANAGER only respond — both appear in the FR role list because both need view/respond access.</li></ul><h2 id="uc-35-—-approve-media-package" tabindex="-1">UC-35 — Approve Media Package <a class="header-anchor" href="#uc-35-—-approve-media-package" aria-label="Permalink to &quot;UC-35 — Approve Media Package&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> OWNER/MANAGER/CLIENT</li><li><strong>Description:</strong> Both parties confirm agreement on the finalized media package.</li><li><strong>Precondition:</strong> Package negotiation (UC-34) has converged.</li><li><strong>Main Flow:</strong><ol><li>Agency side (Owner/Manager) approves.</li><li>Client side approves.</li><li>System marks Media Package as <code>APPROVED</code> only when <strong>both</strong> sides have approved.</li></ol></li><li><strong>Business Rule:</strong> Requires two-sided consensus — Agency internal approval alone is not sufficient (differs from legacy single-sided approval).</li></ul><h2 id="uc-36-—-create-media-campaign" tabindex="-1">UC-36 — Create Media Campaign <a class="header-anchor" href="#uc-36-—-create-media-campaign" aria-label="Permalink to &quot;UC-36 — Create Media Campaign&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> OWNER/MANAGER/CLIENT</li><li><strong>Description:</strong> Build a detailed execution strategy tailored to the client&#39;s brand, based on the selected media package.</li><li><strong>Precondition:</strong> Media Package is <code>APPROVED</code>.</li><li><strong>Main Flow:</strong><ol><li>Agency drafts a Media Campaign — a detailed execution plan matching the Client&#39;s brand (not a contract; the Package is the &quot;framework contract&quot;, Campaign is the execution plan).</li><li>Campaign details submitted for review.</li></ol></li><li><strong>Business Rule:</strong> Media Campaign ≠ contract — it is the execution strategy layered on top of the already-approved Package.</li></ul><h2 id="uc-37-—-approve-launch-media-campaign" tabindex="-1">UC-37 — Approve &amp; Launch Media Campaign <a class="header-anchor" href="#uc-37-—-approve-launch-media-campaign" aria-label="Permalink to &quot;UC-37 — Approve &amp; Launch Media Campaign&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> OWNER/MANAGER/CLIENT</li><li><strong>Description:</strong> Once both parties agree, push all campaign work items into the Workspace backlog.</li><li><strong>Precondition:</strong> Media Campaign drafted (UC-36).</li><li><strong>Main Flow:</strong><ol><li>Both Agency and Client approve the Campaign.</li><li>System auto-generates Task backlog entries from Campaign work items (task name + rough timing only — not yet detailed; see <a href="./../05-content-task-workflow.html">05-content-task-workflow.md</a> UC &quot;Define Task Detail&quot;).</li></ol></li><li><strong>Postcondition:</strong> Campaign becomes <strong>immutable</strong> — no further edits. Mid-campaign additions must go through Content Request (UC-38) or Manager manually adding a Task, not by amending the original Campaign.</li></ul><h2 id="uc-38-—-create-content-request" tabindex="-1">UC-38 — Create Content Request <a class="header-anchor" href="#uc-38-—-create-content-request" aria-label="Permalink to &quot;UC-38 — Create Content Request&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> CLIENT</li><li><strong>Description:</strong> Client creates a new content request, pending Manager review before work is assigned.</li><li><strong>Precondition:</strong> Client is a member of the Workspace.</li><li><strong>Main Flow:</strong><ol><li>CLIENT submits a new content request (independent of the approved Campaign — a supplementary channel).</li><li>Request enters <code>pending</code> status.</li></ol></li><li><strong>Note:</strong> Only CLIENT actually creates requests; OWNER/MANAGER appear in the FR role list solely for view/approve access.</li></ul><h2 id="uc-39-—-process-content-request-status" tabindex="-1">UC-39 — Process Content Request Status <a class="header-anchor" href="#uc-39-—-process-content-request-status" aria-label="Permalink to &quot;UC-39 — Process Content Request Status&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> MANAGER</li><li><strong>Description:</strong> Manager updates request status (pending → in progress → accepted/denied) and moves it into the backlog upon acceptance.</li><li><strong>Precondition:</strong> A Content Request exists in <code>pending</code> status.</li><li><strong>Main Flow:</strong><ol><li>MANAGER reviews the request, transitions status: <code>pending → in progress → accepted</code>.</li><li>On <code>accepted</code>, system auto-generates a new Task in the Workspace backlog, entering the standard Task flow (Define Detail → Assign → Approval Sequence).</li></ol></li><li><strong>Alternate Flow:</strong><ul><li>A1. MANAGER denies the request → status becomes <code>denied</code>, a <strong>terminal</strong> state (differs from Task rejection, which loops back). Client cannot edit a denied request — must submit a brand-new Content Request to re-propose.</li></ul></li></ul><h2 id="uc-40-—-update-content-request" tabindex="-1">UC-40 — Update Content Request <a class="header-anchor" href="#uc-40-—-update-content-request" aria-label="Permalink to &quot;UC-40 — Update Content Request&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> CLIENT</li><li><strong>Description:</strong> Client edits their own content request while it is still in pending status.</li><li><strong>Precondition:</strong> Request status = <code>pending</code>.</li><li><strong>Main Flow:</strong><ol><li>CLIENT edits request content/details.</li><li>System persists changes only while status remains <code>pending</code>.</li></ol></li><li><strong>Alternate Flow:</strong><ul><li>A1. Status has moved past <code>pending</code> (in progress/accepted/denied) → edit blocked.</li></ul></li></ul><h2 id="uc-41-—-cancel-content-request" tabindex="-1">UC-41 — Cancel Content Request <a class="header-anchor" href="#uc-41-—-cancel-content-request" aria-label="Permalink to &quot;UC-41 — Cancel Content Request&quot;">​</a></h2><ul><li><strong>Actor(s):</strong> CLIENT</li><li><strong>Description:</strong> Client cancels their own content request while it is still in pending status.</li><li><strong>Precondition:</strong> Request status = <code>pending</code>.</li><li><strong>Main Flow:</strong><ol><li>CLIENT selects Cancel on their own request, confirms.</li><li>System removes/cancels the request.</li></ol></li><li><strong>Alternate Flow:</strong><ul><li>A1. Status has moved past <code>pending</code> → cancel blocked, Client no longer has authority to cancel.</li></ul></li></ul>',25)])])}const m=t(o,[["render",s]]);export{u as __pageData,m as default};
